parameters.jsCode:
const staticData = $getWorkflowStaticData('global');
staticData.auditLog = staticData.auditLog || [];
const j = $json;
const d = j.aiDecision || {};

const event = {
  event_id: 'EVT-' + j.correlationId,
  timestamp: new Date().toISOString(),
  correlation_id: j.correlationId,
  actor_type: j.actorType,
  actor_reference: j.customerId || j.driverId || j.phone,
  delivery_reference: j.lastOrderReference || null,
  locker_reference: null,
  action: j.gate ? j.gate.action : d.action,
  authorization_result: j.gate ? (j.gate.allowed ? 'ALLOWED' : j.gate.denyReason) : 'N/A',
  result: j.toolErrorCategory || 'N/A',
  failure_code: (j.toolResult && j.toolResult.success === false) ? j.toolErrorCategory : null,
  source: 'n8n-llbox-workflow',
  workflow_version: j.workflowVersion,
  knowledge_version: j.knowledgeVersion
};

// Keep only the last 500 in-memory to bound memory growth. Production should
// send every event to the LLBox backend audit endpoint (see HTTP node above).
staticData.auditLog.push(event);
if (staticData.auditLog.length > 500) staticData.auditLog.shift();

return [{ json: { ok: true, event } }];

const q = $json.query || $json;
const mode = q['hub.mode'] || '';
const token = q['hub.verify_token'] || '';
const challenge = q['hub.challenge'] || '';
let expected = 'llbox-whatsapp-verify';
try {
  const cfg = $('Config').first().json;
  if (cfg && cfg.verifyToken) expected = String(cfg.verifyToken);
} catch (e) {}
const ok = mode === 'subscribe' && token === expected;
return [{ json: { ok, challenge: String(challenge || ''), mode } }];

const now = new Date();
const y = now.getUTCFullYear();
const m = String(now.getUTCMonth() + 1).padStart(2, '0');
const d = String(now.getUTCDate()).padStart(2, '0');
const rand = Math.random().toString(36).slice(2, 10).toUpperCase();
const correlationId = `LLB-WA-${y}${m}${d}-${rand}`;
const cfg = $('Config').item.json;
return [{ json: { ...$json, correlationId, receivedAt: now.toISOString(), workflowVersion: cfg.workflowVersion } }];

const raw = $('WhatsApp Webhook (POST)').item.json;
const corr = $json.correlationId;
const body = raw.body || raw;
const change = body?.entry?.[0]?.changes?.[0]?.value || {};
const message = Array.isArray(change.messages) ? change.messages[0] : null;
const statuses = Array.isArray(change.statuses) ? change.statuses : [];

if (!message && statuses.length) {
  return [{ json: { correlationId: corr, skip: true, isMessage: false, reason: 'delivery_status' } }];
}
if (!message) {
  return [{ json: { correlationId: corr, skip: true, isMessage: false, reason: 'no_message' } }];
}

const type = message.type || 'text';
const text = type === 'text'
  ? String(message.text?.body || '').trim()
  : String(message.image?.caption || message.document?.caption || message.video?.caption || '').trim();
const mediaId = message.audio?.id || message.image?.id || message.document?.id || message.video?.id || '';
const mimeType = message.audio?.mime_type || message.image?.mime_type || message.document?.mime_type || message.video?.mime_type || '';
const filename = message.document?.filename || '';

return [{ json: {
  correlationId: corr,
  skip: false,
  isMessage: true,
  inputType: type,
  messageType: type,
  phone: String(message.from || ''),
  text,
  messageText: text,
  caption: text,
  mediaId,
  mimeType,
  filename,
  messageId: message.id || '',
  waProfileName: change.contacts?.[0]?.profile?.name || '',
  phoneNumberId: change.metadata?.phone_number_id || '',
  waTimestamp: message.timestamp || '',
  reply_mode: type === 'audio' ? 'voice' : 'text'
} }];

// Uses n8n workflow static data as a lightweight store.
// NOTE: static data is per-workflow-instance. For multi-instance/HA n8n
// deployments, replace this with a shared store (Redis/Postgres) or a
// LLBox backend idempotency endpoint.
const staticData = $getWorkflowStaticData('global');
staticData.processedMessages = staticData.processedMessages || {};

const msgId = $json.messageId;
const now = Date.now();
const TTL_MS = 24 * 60 * 60 * 1000; // 24h

// Cleanup old entries opportunistically
for (const [id, ts] of Object.entries(staticData.processedMessages)) {
  if (now - ts > TTL_MS) delete staticData.processedMessages[id];
}

const alreadyProcessed = Boolean(staticData.processedMessages[msgId]);
if (!alreadyProcessed) {
  staticData.processedMessages[msgId] = now;
}

return [{ json: { ...$json, alreadyProcessed } }];

const staticData = $getWorkflowStaticData('global');
staticData.rateWindows = staticData.rateWindows || {};
const cfg = $('Config').item.json;
const limit = parseInt(cfg.rateLimitMessagesPerMinute || '8', 10);
const windowMs = 60 * 1000;
const phone = $json.phone;
const now = Date.now();

const arr = (staticData.rateWindows[phone] || []).filter(ts => now - ts < windowMs);
arr.push(now);
staticData.rateWindows[phone] = arr;

const rateLimited = arr.length > limit;
return [{ json: { ...$json, rateLimited } }];

// Trust level is derived ONLY from backend data — never from user claims
// such as "I am the driver" or "I am the manager".
const parsed = $('Deduplication Check').item.json;
const lookup = $json.data || $json || {};
const contact = lookup.contact || {};

let actorType = 'unknown';
let trustLevel = 'L0';
let verified = false;

if (contact.driverVerified === true && contact.driverId) {
  actorType = 'driver';
  trustLevel = 'L3';
  verified = true;
} else if (contact.customerVerified === true && contact.customerId) {
  actorType = 'customer';
  trustLevel = 'L2';
  verified = true;
} else if (contact.id || contact.name) {
  actorType = 'unknown';
  trustLevel = 'L1';
  verified = false;
} else {
  actorType = 'unknown';
  trustLevel = 'L0';
  verified = false;
}

return [{ json: {
  ...parsed,
  actorType,
  trustLevel,
  verified,
  knownName: (contact.name || '').trim(),
  customerId: contact.customerId || null,
  driverId: contact.driverId || null,
  lastOrderReference: contact.lastOrderReference || '',
  contactRaw: contact
} }];

const staticData = $getWorkflowStaticData('global');
staticData.sessionsV3 = staticData.sessionsV3 || {};
const sessionStore = staticData.sessionsV3;
const cfg = $('Config').item.json;
const now = Date.now();
const timeoutMs = parseInt(cfg.sessionTimeoutMinutes || '30', 10) * 60 * 1000;
const phone = $json.phone;
const text = String($json.text || $json.messageText || '');
const mediaBlob = String($json.imageAnalysis || $json.documentResult || $json.mediaBlob || '');

const extractOrder = (value) => {
  const s = String(value || '').trim();
  if (!s) return '';
  const ocrLine = s.match(/order_reference:\s*([A-Z0-9][A-Z0-9_-]{5,})/i);
  if (ocrLine) {
    const ref = ocrLine[1].toUpperCase();
    const compact = ref.replace(/[^A-Z0-9]/g, '');
    if (compact.length >= 8 && /[0-9]/.test(compact)) return ref;
  }
  const labelMatch = s.match(/\border[\s_-]*(?:id|ref(?:erence)?|number|no)[:\s#-]+([A-Z0-9][A-Z0-9_-]{5,})/i);
  if (labelMatch) {
    const fromLabel = labelMatch[1].toUpperCase();
    if (/^\d{12,22}$/.test(fromLabel) || /^X360/i.test(fromLabel) || /^(ORDER|ORD|AMZ|OD)/i.test(fromLabel)) {
      return fromLabel;
    }
  }
  const stop = new Set([
    'RIDER','DRIVER','ORDER','ORDERS','LOCKER','HELLO','HI','HEY','WHATSAPP','DELIVERY','DELIVER',
    'DELIVERING','PACKAGE','PACKAGES','AMAZON','NOON','LOCATION','ADDRESS','CUSTOMER','OTP','CODE',
    'COLLECT','COLLECTING','COLLECTION','PICKUP','PICK','YES','NO','OK','OKAY','THANKS','THANKYOU',
    'AGENT','PLEASE','HELP','DETAILS','REFERENCE','TRACKING','NUMBER','STATUS','WHERE','WHAT',
    'SEND','NEED','WANT','PARCEL','BOX','LLBOX'
  ]);
  const patterns = [
    /X360[-_][A-Z0-9-]{6,}/i,
    /\bOD\d{10,}\b/i,
    /\b(?:ORDER|ORD)[-_][A-Z0-9]+(?:[-_][A-Z0-9]+)*/i,
    /\b(?:AMZ|AMZN)[-_]?[A-Z0-9]+(?:[-_][A-Z0-9]+)*/i,
    /\bN\d{8,}\b/i,
    /\b\d{12,22}\b/,
    /\b[A-Z]{2,}\d[-A-Z0-9]{5,}\b/i,
    /\b[A-Z0-9]{3,}[-_][A-Z0-9]+(?:[-_][A-Z0-9]+)*/i
  ];
  for (const re of patterns) {
    const m = s.match(re);
    if (!m) continue;
    const ref = m[0].toUpperCase();
    if (/^(ORDER|ORD)[-_]?\d{1,5}$/i.test(ref)) continue;
    if (ref.length < 6) continue;
    const compact = ref.replace(/[^A-Z0-9]/g, '');
    if (stop.has(compact)) continue;
    if (/^ORDERREFERENCE$/i.test(compact) || /^ORDERID$/i.test(compact)) continue;
    if (/^(ORDER|ORD|AMZ|AMZN)[-_][A-Z]+$/.test(ref) && !/[0-9]/.test(ref)) continue;
    if (!/[0-9]/.test(compact) && !/[-_]/.test(ref)) continue;
    if (!/^X360/i.test(ref) && !/[0-9]/.test(compact)) continue;
    return ref;
  }
  return '';
};





const detectCarrier = (value) => {
  const t = String(value || '').toLowerCase();
  if (/\bnoon\b/.test(t)) return 'noon';
  if (/\bamazon\b|\bama[sz]on\b/.test(t)) return 'amazon';
  if (/\brider\b|\bdriver\b/.test(t)) return 'driver';
  return '';
};

const existedBefore = Boolean(sessionStore[phone]);
const firstEverContact = !existedBefore && !$json.knownName;

let session = sessionStore[phone];
if (!session || (now - session.lastActivity) > timeoutMs) {
  session = {
    sessionId: 'SESS-' + phone + '-' + now,
    createdAt: now,
    otpAttempts: 0,
    currentSubState: 'START',
    greeted: false,
    orderReference: '',
    carrier: '',
    role: '',
    deliverySessionId: '',
    boxId: '',
    boxCode: '',
    address: '',
    googleMaps: '',
    otp: '',
    otpExpiresAt: '',
    recipientPhone: '',
    recipientName: '',
    locationSent: false,
    otpSent: false,
    completed: false,
    recentMessages: []
  };
}

const lower = text.toLowerCase();
const wantsClear = /\bdelete\b|\bremove\b|\bcancel\b|\bclear\b|\balready delivered\b|\bwrong order\b|\bnot my (order|package)\b|\bthis isn'?t mine\b/.test(lower);
const wantsNewOrder = /\bnew order\b|\bchange order\b|\badd (this )?(new )?order\b/.test(lower);
const foundOrder = extractOrder(text) || extractOrder(mediaBlob);

if (wantsClear || wantsNewOrder) {
  // Reset delivery cache, but keep order ID if this same message includes it.
  session.deliverySessionId = '';
  session.boxId = '';
  session.boxCode = '';
  session.address = '';
  session.googleMaps = '';
  session.otp = '';
  session.otpExpiresAt = '';
  session.recipientPhone = '';
  session.recipientName = '';
  session.locationSent = false;
  session.otpSent = false;
  session.otpSentCount = 0;
  session.otpAttempts = 0;
  session.completed = false;
  if (foundOrder) {
    session.orderReference = foundOrder;
    session.currentSubState = 'HAS_ORDER_REF';
  } else if (wantsNewOrder) {
    session.orderReference = '';
    session.currentSubState = 'NEED_ORDER_REF';
  } else {
    // Keep existing orderReference so "send OTP" after clear still works.
    session.currentSubState = session.orderReference ? 'HAS_ORDER_REF' : 'NEED_ORDER_REF';
  }
}

if (foundOrder) {
  if (session.orderReference && session.orderReference !== foundOrder) {
    // switching to a new order — reset delivery cache
    session.deliverySessionId = '';
    session.boxId = '';
    session.boxCode = '';
    session.address = '';
    session.googleMaps = '';
    session.otp = '';
    session.otpExpiresAt = '';
    session.recipientPhone = '';
    session.recipientName = '';
    session.locationSent = false;
    session.otpSent = false;
    session.otpSentCount = 0;
    session.otpAttempts = 0;
    session.completed = false;
  }
  session.orderReference = foundOrder;
  session.currentSubState = 'HAS_ORDER_REF';
}

const carrier = detectCarrier(text);
if (carrier) {
  session.carrier = carrier;
  session.role = (carrier === 'driver' || carrier === 'noon' || carrier === 'amazon') ? 'rider' : session.role;
  if (!session.orderReference) session.currentSubState = 'NEED_ORDER_REF';
}
if (/\bcustomer\b|\bcollect\b|\bpick\s*up\b/.test(lower)) session.role = 'customer';
