const j = $json;
const d = j.aiDecision || {};
const staticData = $getWorkflowStaticData('global');
staticData.sessionsV3 = staticData.sessionsV3 || {};
const session = staticData.sessionsV3[j.phone] || {};
const orderReference = j.lastOrderReference || session.orderReference || '';

const MIN_TRUST = {
  none: 'L0', chat: 'L0', ask_name: 'L0', save_name: 'L0',
  get_customer_locker: 'L0', get_locker_location: 'L0',
  register_delivery: 'L0', request_collection_otp: 'L0',
  resolve_delivery_access: 'L0', confirm_delivery: 'L0', clear_locker_session: 'L0',
  create_support_ticket: 'L0', human_escalation: 'L0'
};
const ORDER_REF_ACTIONS = new Set([
  'resolve_delivery_access','request_collection_otp','get_locker_location',
  'register_delivery','confirm_delivery','clear_locker_session'
]);

const action = d.action || 'chat';
const requiredTrust = MIN_TRUST[action];
let allowed = false;
let denyReason = null;

if (requiredTrust === undefined) {
  denyReason = 'ACTION_NOT_ALLOWLISTED';
} else if (ORDER_REF_ACTIONS.has(action) && !orderReference) {
  denyReason = 'MISSING_ORDER_REFERENCE';
} else {
  allowed = true;
}

if (allowed && (action === 'request_collection_otp' || action === 'resolve_delivery_access')) {
  const cfg = $('Config').item.json;
  const limit = parseInt(cfg.rateLimitOtpPerHour || '20', 10);
  const sent = session.otpSentCount || 0;
  const alreadyHaveOtp = Boolean(session.otp) && session.orderReference === orderReference;
  if (!alreadyHaveOtp && sent >= limit) {
    allowed = false;
    denyReason = 'OTP_TOO_MANY_ATTEMPTS';
  }
}

staticData.sessionsV3[j.phone] = session;

return [{ json: {
  ...j,
  lastOrderReference: orderReference,
  gate: {
    allowed,
    denyReason,
    action,
    requiredTrust: requiredTrust || 'L4',
    idempotencyKey: `${j.correlationId}:${j.messageId}:${action}`
  }
} }];

function detectLang(t) {
  if (!t) return 'en';
  if (!/[\u0600-\u06FF]/.test(t)) return 'en';
  const urdu = /[\u0679\u0688\u0691\u06BA\u06C1\u06C2\u06D2\u06CC\u06AF\u06A9]/;
  return urdu.test(t) ? 'ur' : 'ar';
}

const j = $json;
const reason = j.gate.denyReason;
const name = j.knownName || '';
const lang = detectLang(j.text || '');
const greet = name ? (lang === 'en' ? `${name}, ` : `${name}، `) : '';

const MESSAGES = {
