const j = $json;
const backend = $('Config').item.json.backendUrl;
const action = j.gate.action;
const d = j.aiDecision || {};
const session = j.session || {};
const staticData = $getWorkflowStaticData('global');
const liveSession = (staticData.sessionsV3 || staticData.sessions || {})[j.phone] || session;
const orderReference = j.lastOrderReference || liveSession.orderReference || null;
const intent = d.intent || '';

const MAP = {
  get_customer_locker:      { implemented: true,  method: 'POST', path: '/api/tools/find-customer' },
  get_locker_location:      { implemented: true,  method: 'POST', path: '/api/tools/resolve-delivery' },
  register_delivery:        { implemented: true,  method: 'POST', path: '/api/tools/register-delivery' },
