const action = ($json.gate && $json.gate.action) || ($json.aiDecision && $json.aiDecision.action) || 'none';
const needTool = Boolean($json.aiDecision && $json.aiDecision.tool_required) && action && action !== 'none' && action !== 'chat';
let aiReply = ($json.aiDecision && $json.aiDecision.reply) || $json.reply || '';
if (/checking (that |your )?order|send(ing)? (the )?(locker )?location|will send|shortly/i.test(String(aiReply))) {
