    ? `I can't complete that for ${orderRef} through this channel right now. Please try again, or ask for location/OTP again.`
    : 'Please send the order ID / reference so I can help.'
} }];

const prev = $('Build Tool Request').item.json;
const http = $json || {};

let res = {};
let statusCode = http.statusCode;

// fullResponse shape: { statusCode, body, headers }
if (http.body && typeof http.body === 'object' && (http.statusCode || http.headers)) {
  res = http.body;
  statusCode = http.statusCode;
} else if (typeof http.body === 'string') {
  try { res = JSON.parse(http.body); } catch (e) { res = { success: false, message: http.body }; }
  statusCode = http.statusCode;
} else if (http.success === true || http.success === false) {
  res = http;
} else if (http.error) {
  const msg = String(http.error.message || http.error || '');
  const m = msg.match(/(\d{3})\s*-\s*"(.+)"$/s) || msg.match(/(\d{3})\s*-\s*(\{.+\})/s);
  if (m) {
    statusCode = parseInt(m[1], 10);
    try {
      const inner = JSON.parse(m[2].replace(/\\"/g, '"'));
      res = typeof inner === 'string' ? JSON.parse(inner) : inner;
    } catch (e) {
      try { res = JSON.parse(JSON.parse('"' + m[2] + '"')); } catch (e2) {
