    }
  } else {
    res = { success: false, message: msg.slice(0, 300) };
    statusCode = statusCode || 500;
  }
} else {
  res = http;
}

if (typeof res === 'string') {
  try { res = JSON.parse(res); } catch (e) { res = { success: false, message: res }; }
}

if (!res || typeof res !== 'object') res = { success: false, message: 'Empty tool response' };
if (res.success !== true && res.success !== false) {
  res.success = (statusCode >= 200 && statusCode < 300);
}

let category = 'UNKNOWN_ERROR';
if (res.success === true) category = 'SUCCESS';
else if (statusCode === 404) category = 'NOT_FOUND';
else if (statusCode === 401) category = 'UNAUTHORIZED';
else if (statusCode === 403) category = 'FORBIDDEN';
else if (statusCode === 400) category = 'INVALID_INPUT';
else if (statusCode === 409) category = 'CONFLICT';
else if (statusCode === 429) category = 'RATE_LIMITED';
else if (statusCode >= 500) category = 'SYSTEM_UNAVAILABLE';
else if (res.success === false) category = 'INVALID_INPUT';

return [{ json: {
  ...prev,
  toolHttpStatus: statusCode || null,
  toolResult: res,
  toolErrorCategory: category
} }];

// Pass-through merge point: whichever branch fired (success, not-implemented,
// or gate-denied) already set toolResult / toolErrorCategory / reply-relevant fields.
return [{ json: $json }];

function detectLang(t) {
  if (!t) return 'en';
  if (!/[\u0600-\u06FF]/.test(t)) return 'en';
  const urdu = /[\u0679\u0688\u0691\u06BA\u06C1\u06C2\u06D2\u06CC\u06AF\u06A9]/;
  return urdu.test(t) ? 'ur' : 'ar';
}
function pick(en, ar, ur) {
  const lang = detectLang($json.text || '');
  return lang === 'ar' ? ar : lang === 'ur' ? ur : en;
}

const reply = pick(
  'You are sending messages too quickly. Please wait a moment and try again.',
  'يرجى الانتظار قليلاً قبل إرسال رسالة أخرى.',
  'براہ کرم تھوڑی دیر انتظار کریں اور دوبارہ کوشش کریں۔'
);

return [{ json: { ...$json, reply, lastIntent: 'RATE_LIMITED', skipPersist: true } }];

const name = ($json.knownName || '').trim();
const hi = name ? ('Hi ' + name + '! ') : 'Hi! ';
const GREETING = hi + 'I am from LLBox — smart locker deliveries. Are you dropping off a package or collecting one?';
return [{ json: { ...$json, reply: GREETING, finalReply: GREETING, lastIntent: 'GREETING', skipPersist: false } }];

const j = $json;
const d = j.aiDecision || {};

const PRIORITY_MAP = {
  TAMPER: 'P1', SECURITY_BLOCK: 'P2', SYSTEM_UNAVAILABLE: 'P3', STATE_CONFLICT: 'P2'
