return [{ json: { ...j, ticket } }];

const parsed = $('Parse WhatsApp Payload').item.json;

function detectLang(t) {
  if (!t) return 'en';
  if (!/[\u0600-\u06FF]/.test(t)) return 'en';
  const urdu = /[\u0679\u0688\u0691\u06BA\u06C1\u06C2\u06D2\u06CC\u06AF\u06A9]/;
  return urdu.test(t) ? 'ur' : 'ar';
}

const j = { ...parsed, ...$json, phone: parsed.phone, text: parsed.text || $json.text };
const d = j.aiDecision || {};
const name = j.knownName || '';
const lang = detectLang(j.text || '');
const greet = name ? (lang === 'en' ? name + ', ' : name + '\u060c ') : '';
const orderRefRaw = j.lastOrderReference || (j.session && j.session.orderReference) || '';
const bogusOrder = /^(DELIVER|DELIVERY|COLLECT|DRIVER|RIDER|CUSTOMER|PACKAGE|LOCATION|HELLO)$/i.test(String(orderRefRaw).replace(/[^A-Za-z0-9]/g, ''));
const orderRef = (!orderRefRaw || bogusOrder || (!/[0-9]/.test(orderRefRaw) && !/[-_]/.test(orderRefRaw))) ? '' : orderRefRaw;

// EVA-style: start from the conversational AI reply; only enrich when tools ran
let reply = String(j.reply || d.reply || '').trim();

if (j.ticket) {
  const contact = $('Config').item.json.supportPhone;
  reply = greet + "I have raised this with LLBox support (" + j.ticket.ticket_id + "). Someone will follow up soon" + (contact ? " — or call " + contact : '') + ".";
} else if (j.toolResult && j.toolResult.success === true) {
  const data = j.toolResult.data || {};
  const action = j.gate ? j.gate.action : d.action;

  if (action === 'register_delivery') {
    reply = greet + "Done — delivery registered" + (data.boxCode ? " for locker " + data.boxCode : '') + ".";
  } else if (action === 'get_customer_locker') {
    reply = data.userFound
      ? greet + "Your locker is " + (data.locker || data.boxCode || 'assigned') + "."
      : greet + "I could not find a locker on this number yet — do you have an order or tracking number?";
  } else {
    const parts = [];
    if (data.boxCode || data.locker) parts.push("Locker: " + (data.boxCode || data.locker));
    if (data.address) parts.push("Address: " + data.address);
    if (data.googleMaps) parts.push("Map: " + data.googleMaps);
    if (data.otp) parts.push("OTP: " + data.otp + (data.otpExpiresAt ? " (expires " + data.otpExpiresAt + ")" : ''));
    reply = parts.length
      ? greet + parts.join('. ') + '.'
      : greet + "Found it" + (orderRef ? " for " + orderRef : '') + " — " + (j.toolResult.message || "need the location or OTP?");
  }

  const staticData = $getWorkflowStaticData('global');
  staticData.sessions = staticData.sessions || {};
  if (staticData.sessions[j.phone] && orderRef) {
    staticData.sessions[j.phone].orderReference = orderRef;
    staticData.sessions[j.phone].currentSubState = 'RESOLVED';
    staticData.sessions[j.phone].lastActivity = Date.now();
  }
} else if (j.toolResult && j.toolResult.success === false) {
  reply = greet + "I could not verify that" + (orderRef ? " for " + orderRef : '') + ". " + (j.toolResult.message || "Double-check the number or tell me and I will connect support.");
} else if (j.gate && j.gate.allowed === false && j.gate.denyReason === 'MISSING_ORDER_REFERENCE') {
  if (j.userConfused || j.isHelpQuestion || ['HELP_FIND_REFERENCE','HOW_TO_HELP','GREETING'].includes(d.intent)) {
    reply = reply || d.reply;
  } else {
    reply = greet + "Send me the order or tracking number from your SMS, app, or package label and I will get the details for you.";
  }
}

if (!reply || /i am here to help with llbox deliveries and lockers/i.test(reply.toLowerCase())) {
  if (orderRef) {
    reply = greet + "I have order " + orderRef + ". Need the locker location or OTP?";
  } else if (j.userConfused || j.isHelpQuestion) {
    reply = d.reply || greet + "The tracking number is usually in your delivery SMS or on the package label — send it when you have it.";
  } else if (j.carrier || /\bnoon\b|\bamazon\b|\bdriver\b/i.test(j.text || '')) {
    reply = greet + "Send me the order or tracking number from the label and I will share the locker location.";
  } else {
    reply = greet + "Are you delivering or collecting? If you have an order or tracking number, send it over.";
  }
}

// One WhatsApp bubble — EVA-style concise reply
reply = reply.replace(/\n+/g, ' ').replace(/\s{2,}/g, ' ').trim();
if (reply.length > 500) reply = reply.slice(0, 497) + '...';

return [{ json: { ...j, finalReply: reply, lastOrderReference: orderRef } }];

